INSERT INTO accounting_journals (id, journal_number, source_type, source_key, source_id, branch_id, branch_name, entry_date, description, status, created_by_user_id, created_by_name, updated_by_user_id, updated_by_name, posted_by_user_id, posted_by_name, posted_at) SELECT h.id, h.journal_number, 'HISTORICAL', h.source_key, h.source_id, b.id, 'KONSOLIDASI (JKT anchor)', h.entry_date, h.description, 'POSTED', u.id, u.name, u.id, u.name, NULL, NULL, NULL FROM tmp_lgm_hist26_journals h JOIN branches b ON b.code = 'JKT' JOIN (SELECT id, name FROM users WHERE role = 'ADMIN' AND status = 'ACTIVE' ORDER BY created_at, id LIMIT 1) u ON 1 = 1 WHERE h.debit_total = h.credit_total AND EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'accounting_journals' AND COLUMN_NAME = 'source_type' AND COLUMN_TYPE LIKE '%HISTORICAL%') AND NOT EXISTS (SELECT 1 FROM tmp_lgm_hist26_lines l WHERE (SELECT COUNT(*) FROM chart_of_accounts c WHERE c.code = l.coa_code) <> 1) AND NOT EXISTS (SELECT 1 FROM tmp_lgm_hist26_journals x JOIN accounting_journals e ON e.source_type = 'HISTORICAL' AND e.source_key = x.source_key WHERE e.id <> x.id OR e.journal_number <> x.journal_number OR e.source_id <> x.source_id OR e.entry_date <> x.entry_date OR e.description <> x.description) AND NOT EXISTS (SELECT 1 FROM tmp_lgm_hist26_journals x JOIN accounting_journals e ON e.id = x.id WHERE e.source_type <> 'HISTORICAL' OR e.source_key <> x.source_key OR e.journal_number <> x.journal_number) AND NOT EXISTS (SELECT 1 FROM tmp_lgm_hist26_journals x JOIN accounting_journals e ON e.journal_number = x.journal_number WHERE e.source_type <> 'HISTORICAL' OR e.source_key <> x.source_key OR e.id <> x.id) AND NOT EXISTS (SELECT 1 FROM accounting_journals e WHERE (e.source_type = 'HISTORICAL' AND e.source_key = h.source_key) OR e.id = h.id OR e.journal_number = h.journal_number);
INSERT INTO accounting_journal_lines (id, journal_id, line_no, coa_id, memo, direction, amount) SELECT l.id, h.id, l.line_no, c.id, l.memo, l.direction, l.amount FROM tmp_lgm_hist26_lines l JOIN tmp_lgm_hist26_journals s ON s.source_key = l.source_key JOIN accounting_journals h ON h.id = s.id AND h.source_type = 'HISTORICAL' AND h.source_key = s.source_key AND h.journal_number = s.journal_number AND h.source_id = s.source_id AND h.entry_date = s.entry_date AND h.description = s.description JOIN (SELECT code, MIN(id) AS id FROM chart_of_accounts GROUP BY code HAVING COUNT(*) = 1) c ON c.code = l.coa_code WHERE NOT EXISTS (SELECT 1 FROM accounting_journal_lines x WHERE x.id = l.id OR (x.journal_id = h.id AND x.line_no = l.line_no));
