-- IMPORT JURNAL HISTORIS 2026 - PT LENTERA GLOBAL MARITIM
-- Sumber: GL All dari Laporan Jan - Des PT LGM 2026 - Update - Copy (2).xlsx. Data sampai 2026-10-20.
-- Sebelum menjalankan: backup database, pilih database aplikasi, dan pastikan accounting tables, branch JKT, COA, Admin aktif,
-- serta migrasi 20261029_add_accounting_role_and_journals.sql dan 20261032_add_historical_accounting_source.sql sudah diterapkan.
-- Script ini idempotent: source key/ID stabil, jurnal yang sudah cocok tidak digandakan, baris yang kurang dapat dilengkapi.
-- Rekonsiliasi dengan dump accounting_journals 2025 yang diberikan: 543 header, tanpa benturan ID/nomor/source key/source ID.
-- Jurnal tanpa nomor voucher diimpor per rentang baris GL berurutan yang seimbang. Baris bernilai nol diabaikan.
-- PV/26/02/006 dan PV/26/02/008 digabung sesuai konfirmasi pengguna; debit/kredit gabungan Rp43.500.000.
-- Kode COA DT01002 unik dipetakan berdasarkan kode; nama di workbook berbeda dari label COA master, tetapi memo sumber menyebut RRLM.
SET NAMES utf8mb4;
CREATE TEMPORARY TABLE tmp_lgm_hist26_journals (source_key VARCHAR(180) CHARACTER SET ascii COLLATE ascii_bin NOT NULL PRIMARY KEY, id VARCHAR(100) CHARACTER SET ascii COLLATE ascii_bin NOT NULL UNIQUE, journal_number VARCHAR(40) NOT NULL UNIQUE, source_id VARCHAR(100) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, entry_date DATE NOT NULL, description TEXT NOT NULL, expected_line_count INT UNSIGNED NOT NULL, debit_total DECIMAL(30,2) NOT NULL, credit_total DECIMAL(30,2) NOT NULL) ENGINE=InnoDB;
CREATE TEMPORARY TABLE tmp_lgm_hist26_lines (id VARCHAR(100) CHARACTER SET ascii COLLATE ascii_bin NOT NULL PRIMARY KEY, source_key VARCHAR(180) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, line_no SMALLINT UNSIGNED NOT NULL, coa_code VARCHAR(20) CHARACTER SET ascii COLLATE ascii_general_ci NOT NULL, memo VARCHAR(250) NOT NULL, direction ENUM('DEBIT', 'CREDIT') NOT NULL, amount DECIMAL(30,2) NOT NULL, UNIQUE KEY uq_tmp_hist26_source_line (source_key, line_no)) ENGINE=InnoDB;
START TRANSACTION;
SELECT CASE WHEN matched_headers = expected_headers AND matched_lines = expected_lines THEN 'OK - import lengkap / sudah sesuai, tidak ada duplikat' ELSE 'PERIKSA - ada prasyarat/konflik; jumlah cocok tidak lengkap' END AS import_status, expected_headers, matched_headers, expected_lines, matched_lines, expected_debit, expected_credit FROM (SELECT (SELECT COUNT(*) FROM tmp_lgm_hist26_journals) AS expected_headers, (SELECT COUNT(*) FROM tmp_lgm_hist26_lines) AS expected_lines, (SELECT COUNT(*) FROM tmp_lgm_hist26_journals s JOIN accounting_journals h ON h.id = s.id AND h.source_type = 'HISTORICAL' AND h.source_key = s.source_key AND h.journal_number = s.journal_number AND h.source_id = s.source_id AND h.entry_date = s.entry_date AND h.description = s.description) AS matched_headers, (SELECT COUNT(*) FROM tmp_lgm_hist26_lines l JOIN tmp_lgm_hist26_journals s ON s.source_key = l.source_key JOIN accounting_journals h ON h.id = s.id AND h.source_type = 'HISTORICAL' AND h.source_key = s.source_key JOIN (SELECT code, MIN(id) AS id FROM chart_of_accounts GROUP BY code HAVING COUNT(*) = 1) c ON c.code = l.coa_code JOIN accounting_journal_lines x ON x.id = l.id AND x.journal_id = h.id AND x.line_no = l.line_no AND x.coa_id = c.id AND x.memo = l.memo AND x.direction = l.direction AND x.amount = l.amount) AS matched_lines, (SELECT SUM(debit_total) FROM tmp_lgm_hist26_journals) AS expected_debit, (SELECT SUM(credit_total) FROM tmp_lgm_hist26_journals) AS expected_credit) report;
SELECT 'Historical 2026 import totals in database' AS report, COUNT(*) AS journal_count, (SELECT COUNT(*) FROM accounting_journal_lines l JOIN accounting_journals j ON j.id = l.journal_id WHERE j.source_type = 'HISTORICAL' AND j.source_key LIKE 'lgm-gl-2026-%') AS line_count, MIN(entry_date) AS first_date, MAX(entry_date) AS last_date FROM accounting_journals WHERE source_type = 'HISTORICAL' AND source_key LIKE 'lgm-gl-2026-%';
COMMIT;
